import{_ as a,o as i,c as s,ao as t}from"./chunks/framework.CT_uKIOa.js";const u=JSON.parse('{"title":"Recording guide","description":"","frontmatter":{},"headers":[],"relativePath":"recording.md","filePath":"recording.md","lastUpdated":null}'),r={name:"recording.md"};function n(o,e,l,d,p,c){return i(),s("div",null,[...e[0]||(e[0]=[t(`<h1 id="Recording-guide" tabindex="-1">Recording guide <a class="header-anchor" href="#Recording-guide" aria-label="Permalink to &quot;Recording guide {#Recording-guide}&quot;">​</a></h1><p>Recordings in this gallery are produced with <a href="https://github.com/AtelierArith/Replay.jl" target="_blank" rel="noreferrer">Replay.jl</a> and <code>asciinema</code>, then reviewed before they are committed. See the <a href="https://github.com/AtelierArith/ReplayGallery.jl#record-an-example" target="_blank" rel="noreferrer">repository README</a> for the full workflow and safety notes; this page is a short version.</p><h2 id="Prerequisites" tabindex="-1">Prerequisites <a class="header-anchor" href="#Prerequisites" aria-label="Permalink to &quot;Prerequisites {#Prerequisites}&quot;">​</a></h2><ul><li><p>The exact Julia version in <code>julia-version</code> (currently 1.13.3), and Python 3.11+.</p></li><li><p><code>asciinema</code> 2.4.0 (<code>python -m pip install asciinema==2.4.0</code>).</p></li><li><p>A POSIX PTY environment (Linux or macOS; use WSL on Windows).</p></li></ul><p><code>record.py</code> checks <code>julia --version</code> against <code>julia-version</code> before doing any work, so a locally installed LTS or a newer stable release cannot silently produce a recording with a different runtime.</p><h2 id="Record-an-example" tabindex="-1">Record an example <a class="header-anchor" href="#Record-an-example" aria-label="Permalink to &quot;Record an example {#Record-an-example}&quot;">​</a></h2><p>From the repository root:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">julia</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --startup-file=no</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --project=.</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/setup.jl</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/record.py</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> helloworld</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">asciinema</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> play</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> artifacts/helloworld.cast</span></span></code></pre></div><p><code>scripts/setup.jl</code> pins Replay to the commit in <code>replay-source.toml</code>. The recorder copies the example into a temporary working environment, warms up packages, records with fixed terminal dimensions, and checks the cast and Julia error output. Output is replaced only after a successful recording.</p><h2 id="Review-and-import" tabindex="-1">Review and import <a class="header-anchor" href="#Review-and-import" aria-label="Permalink to &quot;Review and import {#Review-and-import}&quot;">​</a></h2><p>Recordings execute Julia code. Review the example and the produced cast before committing, and use a clean Julia depot (<code>JULIA_DEPOT_PATH</code>) as CI does. Import the recording workflow artifact with:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/import_recording.py</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> NAME</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ARTIFACT_DIRECTORY</span></span></code></pre></div><p>The importer refuses mismatched source inputs or corrupt casts, and preserves the resolved manifests under <code>recordings/manifests/</code>.</p><h2 id="Adding-an-example" tabindex="-1">Adding an example <a class="header-anchor" href="#Adding-an-example" aria-label="Permalink to &quot;Adding an example {#Adding-an-example}&quot;">​</a></h2><ol><li><p>Add <code>examples/&lt;name&gt;/app.jl</code> (and a <code>Project.toml</code> if it needs packages).</p></li><li><p>Add an entry to <a href="https://github.com/AtelierArith/ReplayGallery.jl/blob/main/examples.json" target="_blank" rel="noreferrer"><code>examples.json</code></a>.</p></li><li><p>Record it and commit the cast plus the updated provenance.</p></li><li><p>Rebuild this site; the example page is generated from the catalog automatically.</p></li></ol>`,15)])])}const m=a(r,[["render",n]]);export{u as __pageData,m as default};
